  ["Stereo module not installed."] = "Stereo modul není nainstalován.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Háčky enginu se nenačetly, takže vše níže je neaktivní a headset běží v prosté mono cestě. Buď je CyberpunkVR_StereoModuleEnable 0, nebo existuje bin\\x64\\vrport_nostereo.txt. Viz řádek \"Stereo:\" v cyberpunkvrport.log.",
  ["LEFT"] = "LEVÉ",
  ["RIGHT"] = "PRAVÉ",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Stereo aktivní  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Teď chybí druhé oko -> obě oči dostávají MAIN (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "V nabídkách a při načítání normální. Pokud to tak zůstane ve hře: komponenta VRCAM je vypnutá, nebo vrcam.json uvádí kameru, kterou entita hráče nemá.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Odesílání sterea vypnuto -> obě oči dostávají MAIN (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "stáří oka vrcam %u ms  (zastaralé po %u)   odeslání oka %llu",
  ["vrcam eye: never produced a frame"] = "oko vrcam: ještě nevytvořilo snímek",
  ["Send VRCAM to the %s EYE"] = "Posílat VRCAM do oka: %s",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Vyp. = staré chování, MAIN zdvojené do obou očí.\nZap. = %s oko dostane vlastní výslednou barvu pohledu VRCAM --\nstejný obraz, jaký ukazuje zrcadlo na ploše -- překódovaný do\nformátu sRGB swapchainu a zmenšený na velikost oka.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "kopie snímku %llu   přeskočení %llu   zásahy RTV vrcam %llu",
  ["Eye staleness limit (ms)"] = "Limit zastarání oka (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Jak dlouho zůstává poslední snímek VRCAM použitelný. Potom %s\noko přejde na MAIN -- jedno zamrzlé oko, zatímco se druhé hýbe,\nje mnohem horší na pohled než mono.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (řídí se upscalerem MAIN, bez přepínače)",
  ["ON"] = "ZAPNUTO",
  ["off"] = "vyp.",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Zapnuto, kdykoli MAIN upscaluje přes DLSS: vrcam dostane vlastní\nviewport Streamline a renderuje pod svým cílem.\nVypnuto při DLAA / TAA / bez upscaleru. Mění se v grafickém\nnastavení hry, ne tady.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "Sladit projekci VRCAM s MAIN  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "Komponenta VRCAM  (přepínač RTTI: vynutit ZAP/VYP)",
  ["component %s   camera %s"] = "komponenta %s   kamera %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "uzly pohledu: main %llu   ostatní %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "Zrcadlo VRCAM  (samostatné okno, pro záznam)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Diagnostika",
  ["Compact ADS camera telemetry (in-headset)"] = "Kompaktní telemetrie kamery ADS (v headsetu)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Malý panel, který zůstane po zavření F10 a ukazuje, co ENGINE udělal s kamerou při zvednutí mířidel:\nrozdíl a špička v centimetrech, vpravo/vpřed/nahoru v bázi směru, oproti základu z palby od boku.\nOdesílání sterea to neovlivní.",
  ["Telemetry X"] = "Telemetrie X",
  ["Telemetry Y"] = "Telemetrie Y",
  ["Normalised position in the eye image"] = "Normalizovaná poloha v obrazu oka",
  ["Stereo logging -> cyberpunkvrport.log"] = "Záznam sterea -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Potvrzený snímek výsledku VRCAM",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Vyp. = číst dočasný cíl enginu přímo. Tento cíl je\nalokace frame graphu, kterou pozdější průchod znovu použije, což\nzpůsobovalo střídání světlého/tmavého obrazu. Nechte zapnuté.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Snímek v uzlu tonemapu místo RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "CPU profiler uzlů  (vlastní+celk. ms na uzel)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "snímek %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Audit uzlů -> záznam  (vynuluje okno)",
  ["top %d by self ms/frame   (main | vrcam)"] = "top %d podle vlastních ms/snímek   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Řízení -- ruce na volantu",
  ["Grab the wheel with the grips"] = "Chytat volant gripy",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Při ŘÍZENÍ přibližte ruku tam, kde animace řízení drží\nvolant (nebo řídítka), a stiskněte grip: paže se vrátí\nk vlastní animaci hry -- ruka na volantu, prsty kolem\nněj -- místo sledování ovladače. Pusťte grip a vrátí se\nk vaší ruce.\n\nKaždá ruka je nezávislá: jednou držte volant a druhou\nzbraň. Dokud je ruka na volantu, tento grip nedělá nic jiného (žádné\ntasení z pouzdra, žádné chycení zásobníku).",
  ["Grab radius (m)"] = "Poloměr úchopu (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Jak blízko animované ruky musí být vaše ruka, aby se\ngrip počítal jako úchop volantu. Větší = snáz chytíte\nvolant, který nevidíte; příliš velký a každý úchop v autě chytí volant.",
  ["Car full lock at (deg)"] = "Plný rejd při (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Citlivost volantu: otočení ruky od místa úchopu po plný rejd.\nJedna ruka používá náboj zkalibrovaný v místě úchopu; dvě spojnici mezi nimi.\nPřidání nebo puštění ruky zachová aktuální natočení.\n180 = půl otáčky na doraz na každou stranu (výchozí). Méně = citlivější.\nVolant v kabině má dvojnásobný nativní rozsah; rejd kol se nemění.\nRozsah za plným rejdem zachovává stejnou neutrální polohu.",
  ["Steering deadzone (deg)"] = "Mrtvá zóna řízení (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Náklon kolem středu, který vůbec nezatáčí.\nZvyšte, pokud auto táhne, když držíte volant rovně;\nkaždý stupeň zde je stupeň mrtvého volantu mimo střed.\nCelý rozsah stále končí na „Plný rejd při“, takže rozšíření\nmrtvé zóny nezpůsobí skok řízení.",
  ["Steering prediction"] = "Předvídání řízení",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Jemně předvídá pokračující zatáčku podle nedávného pohybu ruky.\nOmezeno na 8 ms a 0.5°; neutrál se nemění.\nPředvídání se zastaví při pauze, obratu nebo změně úchopu.\nVe výchozím stavu vyp. Začátek zatáčky předvídat nedokáže.",
  ["Prediction horizon (ms)"] = "Horizont předvídání (ms)",
  ["Horn -- hand on the wheel hub"] = "Klakson -- ruka na náboji volantu",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Při ŘÍZENÍ položte ruku doprostřed volantu -- tam, kde byste\nbouchli do skutečného klaksonu -- a auto troubí, dokud tam ruka je.\nGrip není potřeba; ruka, která volant DRŽÍ, nikdy netroubí.",
  ["Horn hub radius (m)"] = "Poloměr náboje klaksonu (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Jak blízko středu volantu se ruka počítá na náboji.\nVětší = klakson snáz najdete naslepo; příliš velký\na sahá až k věnci, takže každý úchop troubí.",
  ["Trigger fires the gun while driving"] = "Spoušť střílí při řízení",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Vytáhněte zbraň na místě řidiče a PRAVÁ SPOUŠŤ přestane být\nplynem a stane se zbraní: řiďte levou rukou na volantu a\nstřílejte pravou.\n\nPlyn se ZAARETUJE na hodnotě z okamžiku tasení, takže\nauto dál jede a LEVÁ PÁČKA vpřed/vzad doladí rychlost, zatímco\nstřílíte. Schovejte zbraň a spoušť je opět plyn.\n\nDokud je zbraň venku, vpřed/vzad levé páčky patří\ndoladění: žádné naklánění / houpání ani gesto autopilota, dokud zbraň neschováte.",
  ["Throttle trim rate (/s)"] = "Rychlost doladění plynu (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Kolik z celého rozsahu plynu levá páčka přidá nebo\nubere za sekundu, když je zbraň venku.\n0.5 = dvě sekundy držení od volnoběhu po plný plyn.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "řízení %d   u volantu  L %d R %d   úchop  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "řízení  %+.1f°  ->  páčka %+.2f     klakson  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "POSUN KAMERY VSEDĚ",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Posuny hlavy v OBECNÉ jsou kalibrace vestoje. Vsedě je kamera vozidla\nhry už tam, kde má být -- proto port ve vozidle zahodí\nsvé dvě automatické hodnoty -- takže posun pro stání odnese pohled\nze sedadla, místo aby ho opravil.\n\nTyto tři se přičítají k posuvníkům hlavy, když jste ve vozidle, a\nignorují se, jakmile vystoupíte, takže auto a ulici lze ladit\nzvlášť. Nula = auto si ponechá přesně dnešní posun.",
  ["Car Head X right"] = "Hlava v autě X vpravo",
  ["Car Head Y forward"] = "Hlava v autě Y vpřed",
  ["Car Head Z up"] = "Hlava v autě Z nahoru",
  ["   (window combat: use GENERAL > Head offsets)"] = "   (boj z okna: použijte OBECNÉ > posuny hlavy)",
  ["   (in a vehicle: these are live)"] = "   (ve vozidle: aktivní)",
  ["   (on foot: these are ignored)"] = "   (pěšky: ignorováno)",
  ["FPS overlay"] = "Překryv FPS",
  ["Overlay layout"] = "Rozvržení překryvu",
