  ["Optical flow"] = "Optický tok",
  ["Off (game vectors only)"] = "Vyp. (jen vektory hry)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "Vektory pohybu hry už popisují téměř veškerý pohyb; optický tok přidává čas GPU\na paměť pro to, co jim unikne (některé částice a efekty).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "Model generování snímků NVIDIA na vektorech pohybu a hloubce hry. Nejvyšší kvalita, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Adaptivní tempo skutečných snímků",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Až polovina obnovovací frekvence headsetu. Nechá generovaným snímkům víc času GPU, když sousední skutečné snímky nestíhají.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "Používá vektory pohybu a hloubku hry v obou očích. Přidá jeden mezisnímek mezi skutečné snímky.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "Zapnout panel HUD",
  ["Head / free-look cone"] = "Hlava / kužel volného rozhledu",
  ["Follow"] = "Sledování",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Dotahuje mimo kužel, nebo po 3 sekundách klidu, když je odchylka stáčení uvnitř nad 10°.",
  ["HUD FOV"] = "FOV HUD",
  ["Stereo depth"] = "Stereo hloubka",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Vyp.: HUD má v obou očích stejný směr.\nZap.: umístí ho do zvolené fyzické hloubky.",
