  ["Glow"] = "Záře",
  ["INTERACTIONS / DIALOGS"] = "INTERAKCE / DIALOGY",
  ["World-space interactions / dialogs"] = "Interakce / dialogy v prostoru",
  ["Interaction free-look cone"] = "Kužel volného rozhledu interakcí",
  ["Loot free-look cone"] = "Kužel volného rozhledu kořisti",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Používá se, když je vidět panel kořisti a popis předmětu. Výchozí: 10°.",
  ["Interaction distance"] = "Vzdálenost interakcí",
  ["Interaction FOV"] = "FOV interakcí",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Výzvy k interakci a volby v dialogu sdílejí tento panel. Následuje jen mimo kužel; bez zpožděného dotahování v klidu.",
  ["Element"] = "Prvek",
  ["Not currently visible in gameplay; settings are still saved."] = "Teď ve hře není vidět; nastavení se přesto ukládá.",
  ["Show element"] = "Zobrazit prvek",
  ["Horizontal offset"] = "Vodorovný posun",
  ["Vertical offset"] = "Svislý posun",
  ["Size"] = "Velikost",
  ["Opacity"] = "Krytí",
  ["Reset element"] = "Obnovit prvek",
  ["Reset all elements"] = "Obnovit všechny prvky",
  ["CONTROLS"] = "OVLÁDÁNÍ",
  ["DRIVING"] = "ŘÍZENÍ",
  ["BINDINGS"] = "PŘIŘAZENÍ",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Pohyb, míření a zkratky fyzických interakcí.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Míření rukou  (vyp. = oddělené míření hlavou VR)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "ZAP (míření rukou): ovladač míří zbraní a VRIK ovládá paže.\nVYP (oddělené míření hlavou VR): ZBRAŇ místo toho sleduje hlavu, hra\nsi ponechá její polohu a animace ADS a VRIK uvolní\npaži se zbraní. V obou případech výstřel vychází ze skutečného ústí, pro kulky\ni projektily, a volný rozhled při míření zůstává.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Laserová tečka zbraně (kam kulka dopadne)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Červená tečka promítnutá ze skutečného směru ústí přes\nkameru hry -- ukazuje přesně, kam kulka poletí.",
  ["Controller vibration"] = "Vibrace ovladačů",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Haptika: každý výstřel podle třídy zbraně (pistole, puška, brokovnice, odstřelovačka),\nblok a odražení v boji zblízka, blok a odklonění kulek, sáhnutí po prvku opasku,\nvytažení pojistky granátu. Úchop oběma rukama: obě ruce; jednou rukou: jedna.",
  ["Vibration strength"] = "Síla vibrací",
  ["Enable VR -> XInput merge"] = "Zapnout slučování VR -> XInput",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Sloučí (OR) stav ovladačů VR do gamepadu XInput 0 při každém dotazu.\nVyp. = hra vidí jen fyzický ovladač / nic.",
  ["Weapon holsters (reach + right grip)"] = "Pouzdra zbraní (sáhnout + pravý grip)",
  ["Immersive holsters"] = "Imerzivní pouzdra",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "ZAP - zbraň vybírá VIDITELNÉ pouzdro, po kterém sáhnete:\n      přes pravé rameno = hlavní zbraň (puška / odstřelovačka),\n      bok s katanou = zblízka, bok s pistolí = vedlejší zbraň.\nVYP - viditelná pouzdra se ignorují, pevný slot na zónu:\n      přes rameno = EquipmentSlot1, pravý bok = Slot2, levý bok = Slot3.\nSáhněte do zóny a stiskněte PRAVÝ grip pro vybavení / schování.",
  ["Locomotion direction"] = "Směr pohybu",
  ["Analog movement"] = "Analogový pohyb",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Zap.: rychlost sleduje výchylku levé páčky. Vyp.: dosavadní pohyb pevnou rychlostí (výchozí).\nOvládání vozidel si ponechá dosavadní odezvu.",
  ["Left stick deadzone"] = "Mrtvá zóna levé páčky",
  ["Right stick deadzone"] = "Mrtvá zóna pravé páčky",
  ["Full input threshold"] = "Práh plného vstupu",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Surová výchylka, která dává plný analogový vstup a spouští sprint, úskok a přikrčení.\nUžitečná výchylka mezi mrtvou zónou a tímto prahem odpovídá 0-100%%.",
  ["Game (camera)"] = "Hra (kamera)",
  ["HMD (head)"] = "HMD (hlava)",
  ["Left hand"] = "Levá ruka",
  ["Right hand"] = "Pravá ruka",
  ["Move source"] = "Zdroj směru pohybu",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Hra      - levá páčka jde tam, kam se dívá kamera (původní).\nHMD      - levá páčka jde tam, kam se dívá headset.\nLevá/pravá ruka - jde tam, kam míří zvolený ovladač.\nVozidla vždy zachovávají směr hry.",
  ["Breaststroke swimming"] = "Plavání prsa",
  ["Physical crouch"] = "Fyzické přikrčení",
  ["Physical crouch depth"] = "Hloubka fyzického přikrčení",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Ztráta výšky po změřeném náklonu. Narovnání fyzické přikrčení ukončí.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "Ve vodě: natáhněte obě ruce dopředu, rozevřete je a přitáhněte dozadu.\nPohyb začíná během záběru. Klidné záběry plavou normálně; rychlé dají zrychlení.\nPlavete tam, kam míří headset, i nahoru/dolů; páčka není potřeba.\nPro vynoření zvedněte rozevřené ruce k hrudi a stlačte obě dolů.\nOpakujte záběry pro další plavání. Pro zastavení přitáhněte levou páčku dozadu.",
  ["Ladder grip climbing"] = "Šplhání po žebříku gripy",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Chyťte boční štěřinu nebo příčku. Táhněte ruku dolů pro lezení nahoru,\nnebo ji posuňte nahoru pro sestup. Pusťte pro zastavení. Pánev a nohy zůstávají na žebříku.",
  ["Auto finish near ladder top"] = "Automatické dokončení u vrcholu žebříku",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Po přítahu nahoru u vrcholu dokončí výstup, i když jsou gripy puštěné.\nPohněte páčkou nebo zatlačte držící ruku nahoru pro zrušení.",
  ["Ladder finish distance"] = "Vzdálenost dokončení žebříku",
  ["Turning (right stick)"] = "Otáčení (pravá páčka)",
  ["Snap turn"] = "Skokové otáčení",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Převede osu X pravé páčky na jednotlivé skoky otočení\nmísto plynulého otáčení. Pomáhá proti nevolnosti z pohybu.",
  ["Snap angle"] = "Úhel skoku",
  ["STEREO"] = "STEREO",
  ["PERFORMANCE"] = "VÝKON",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Nastavení hry",
  ["Off (higher FPS)"] = "Vyp. (vyšší FPS)",
  ["On (lower latency)"] = "Zap. (nižší latence)",
  ["On + Boost"] = "Zap. + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Vyp. může zlepšit vytížení GPU a FPS, ale může zvýšit vstupní latenci.",
  ["On"] = "Zap.",
  ["Waiting for renderer"] = "Čekání na renderer",
  ["Applied: %s"] = "Použito: %s",
  ["STEREO VIEW"] = "STEREO POHLED",
  ["Mono mode"] = "Mono režim",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Jeden obraz pro obě oči, vykreslený jednou ze středu hlavy:\nbez hloubky, nejvíce snímků. Stereo enginu a druhý pohled jsou vypnuté.",
  ["Restart the game to apply"] = "Restartujte hru pro použití",
  ["Motion prediction (ms)"] = "Předvídání pohybu (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Předvídá pózu hlavy o tolik ms dopředu podle její\nrychlosti a skrývá latenci od vykreslení po fotony. 0 = vyp.\nZvyšujte, dokud pohyb nebude svižný bez přestřelení.",
  ["Stereo separation x"] = "Stereo rozestup x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Osobní doladění automatického IPD. 1.0 = kalibrovaný přirozený\nrozestup, automaticky přepočtený na IPD běhového prostředí headsetu. Posuňte\n0.8-1.2 podle chuti; 3-5x přehání hloubku a dělá\nstřídání očí viditelným na plochém monitoru pro testy.",
  ["World scale"] = "Měřítko světa",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Mění společně rozestup očí A posun hlavy.\nSnižte (např. 0.8), aby svět působil\nVĚTŠÍ / vy menší; zvyšte pro zmenšení světa. Použijte, pokud V\na NPC působí příliš velcí.",
  ["IPD scale"] = "Měřítko IPD",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Násobitel rozestupu očí na IPD běhového prostředí. 1.0 = neutrální\nzáklad (+-0.033 m u typického headsetu).\nOvlivňuje stereo hloubku (diorama vs. obr), NE monokulární velikost.",
  ["Reuse last clean frame"] = "Znovu použít poslední čistý snímek",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Při zastaralých taktech znovu odešle poslední čisté zachycené oko a nechá\nkompozitor ho přeprojektovat, místo opakovaného deformování zastaralého\nobsahu. Může snížit frekvenci odesílání\nk frekvenci zachytávání. Vyp. = vždy deformovat zastaralé oko.",
  ["Asymmetric projection"] = "Asymetrická projekce",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "ZAP: každé oko vykresluje přesně své vlastní mimostředové okno čočky\n(víc využitého panelu, čtvercové pixely).\nVYP: symetrický frustum podle nejširšího polovičního úhlu.",
  ["AVATAR"] = "AVATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "VR zkratky a výchozí herní akce. Názvy tlačítek odpovídají konvenci Touch / Xbox; herní akce používají vaše přiřazení ovladače.",
